-- Narrow URL-format exceptions for the local storage URLs generated by the upload actions.
-- This does not identify an environment: staff authorization, hosted URL rules and audits stay unchanged.
-- News starts from 20260722120000; delegate starts from 20261009170000, retaining its deletion-race check.

create or replace function public.admin_set_news_image(p_id uuid, p_image_url text) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_row public.news%rowtype;
  v_url text := nullif(btrim(coalesce(p_image_url, '')), '');
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if not public.has_any_admin_role('super_admin', 'editor') then
    raise exception 'missing_role';
  end if;
  select * into v_row from public.news where id = p_id;
  if not found then raise exception 'invalid_target'; end if;
  -- pinned to THIS platform's storage origin and the upload action's filename
  -- shape — the RPC pairs with the upload action, so foreign hosts and
  -- hand-crafted paths have no business here
  if v_url is null or char_length(v_url) > 600
     or (v_url !~ '^https://[a-z0-9]{20}\.supabase\.co/storage/v1/object/public/news-images/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}-[0-9]{10,16}\.(jpg|png|webp)$'
         and v_url !~ ('^http://(127[.]0[.]0[.]1|localhost):54321/storage/v1/object/public/news-images/'
                        || p_id::text || '-[0-9]{10,16}[.](jpg|png|webp)$')) then
    raise exception 'invalid_image';
  end if;

  update public.news set image_url = v_url where id = p_id;

  insert into public.audit_log (actor_id, action, target_type, target_id, details)
  values (v_uid, 'news.set_image', 'news', p_id::text,
          jsonb_build_object('title', v_row.title));
end $$;
grant execute on function public.admin_set_news_image(uuid, text) to authenticated;
revoke execute on function public.admin_set_news_image(uuid, text) from public, anon;

create or replace function public.admin_update_delegate_profile(
  p_delegate_id uuid, p_bio text, p_photo_url text
) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_delegate public.delegates%rowtype;
  v_profile public.profiles%rowtype;
  v_bio text := nullif(btrim(coalesce(p_bio, '')), '');
  v_photo text := nullif(btrim(coalesce(p_photo_url, '')), '');
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if not public.has_any_admin_role('super_admin', 'verifier') then
    raise exception 'missing_role';
  end if;
  if v_bio is not null and length(v_bio) > 1000 then raise exception 'invalid_target'; end if;
  if v_photo is not null and (length(v_photo) > 512
     or (v_photo !~ '^https://'
         and v_photo !~ ('^http://(127[.]0[.]0[.]1|localhost):54321/storage/v1/object/public/delegate-photos/'
                          || p_delegate_id::text || '-[0-9]{10,16}[.](jpg|png|webp)$'))) then
    raise exception 'invalid_target';
  end if;
  select * into v_delegate from public.delegates where id = p_delegate_id;
  if not found or v_delegate.status <> 'approved' then raise exception 'invalid_target'; end if;
  select * into v_profile from public.profiles where id = p_delegate_id;

  update public.delegates set bio = v_bio, photo_url = v_photo where id = p_delegate_id;
  if not found then raise exception 'invalid_target'; end if;

  insert into public.audit_log (actor_id, action, target_type, target_id, details)
  values (v_uid, 'delegate.update_profile', 'delegate', p_delegate_id::text,
          jsonb_build_object(
            'name', v_profile.first_name || ' ' || v_profile.last_name,
            'bioChanged', v_bio is distinct from v_delegate.bio,
            'photoChanged', v_photo is distinct from v_delegate.photo_url));
end $$;
grant execute on function public.admin_update_delegate_profile(uuid, text, text) to authenticated;
revoke execute on function public.admin_update_delegate_profile(uuid, text, text) from public, anon;
